import { cookies, headers } from 'next/headers';

export default async function UserPreferences() {
  const cookieStore = await cookies();
  const theme = cookieStore.get('theme')?.value ?? 'light';

  const headersList = await headers();
  const acceptLanguage = headersList.get('accept-language');
  const preferredLanguage = acceptLanguage ? acceptLanguage.split(',')[0] : 'en-US';

  return (
    <section className="p-6 border rounded-lg bg-white shadow-sm max-w-md mx-auto mt-8">
      <h2 className="text-2xl font-bold mb-4 text-gray-800">User Settings</h2>
      <dl className="space-y-3">
        <div className="flex justify-between border-b pb-2">
          <dt className="font-medium text-gray-600">Theme Preference:</dt>
          <dd className="font-semibold text-gray-900 capitalize">{theme}</dd>
        </div>
        <div className="flex justify-between border-b pb-2">
          <dt className="font-medium text-gray-600">Language:</dt>
          <dd className="font-semibold text-gray-900">{preferredLanguage}</dd>
        </div>
      </dl>
    </section>
  );
}

